import { codexEndpoints } from "@shared/http";
import { fromPromise } from "../../runtime";
import {
  approveCodexAction,
  cancelCodexRun,
  getCodexStatus,
  preflightCodexRun,
  readCodexLatestRunSummary,
  readCodexRunEvents,
  resumeCodexRun,
  sendRepositoryChatMessage,
  startCodexRun
} from "../../services/codex";
import { httpRunEventSink } from "./runEventSink";
import { route, type HttpResourceRoute } from "./types";

export const codexRoutes = [
  route(codexEndpoints.status, () => fromPromise(() => getCodexStatus())),
  route(codexEndpoints.preflightRun, (input) => fromPromise(() => preflightCodexRun(input))),
  route(codexEndpoints.startRun, (input) => fromPromise(() => startCodexRun(input, { runEventSink: httpRunEventSink() }))),
  route(codexEndpoints.resumeRun, (input) => fromPromise(() => resumeCodexRun(input, { runEventSink: httpRunEventSink() }))),
  route(codexEndpoints.cancelRun, (input) => fromPromise(() => cancelCodexRun(input))),
  route(codexEndpoints.approveAction, ({ approvalId, decision }) =>
    fromPromise(() => approveCodexAction(approvalId, decision))
  ),
  route(codexEndpoints.sendRepositoryChatMessage, (input) => fromPromise(() => sendRepositoryChatMessage(input))),
  route(codexEndpoints.readRunEvents, ({ projectPath, ticketId, runId }) =>
    fromPromise(() => readCodexRunEvents(projectPath, ticketId, runId))
  ),
  route(codexEndpoints.readLatestRunSummary, ({ projectPath, ticketId }) =>
    fromPromise(() => readCodexLatestRunSummary(projectPath, ticketId))
  )
] satisfies ReadonlyArray<HttpResourceRoute>;

import {
  cancelRunInputSchema,
  codexCancelRunResultSchema,
  codexRunPreflightResultSchema,
  codexRunStartResultSchema,
  codexStatusSchema,
  rendererRunEventSchema,
  repositoryChatInputSchema,
  repositoryChatResponseSchema,
  runSummarySchema,
  startRunInputSchema
} from "../schemas";
import { arrayOf, defineEndpoint } from "./contract";
import {
  approveActionRequestSchema,
  projectTicketRequestSchema,
  projectTicketRunRequestSchema
} from "./common";
import { Schema } from "effect";

export const codexEndpoints = {
  status: defineEndpoint({
    method: "GET",
    path: "/api/codex/status",
    response: codexStatusSchema
  }),
  preflightRun: defineEndpoint({
    method: "POST",
    path: "/api/codex/preflight",
    request: { location: "body", schema: startRunInputSchema },
    response: codexRunPreflightResultSchema
  }),
  startRun: defineEndpoint({
    method: "POST",
    path: "/api/codex/runs",
    request: { location: "body", schema: startRunInputSchema },
    response: codexRunStartResultSchema
  }),
  resumeRun: defineEndpoint({
    method: "POST",
    path: "/api/codex/runs/resume",
    request: { location: "body", schema: startRunInputSchema },
    response: codexRunStartResultSchema
  }),
  cancelRun: defineEndpoint({
    method: "POST",
    path: "/api/codex/runs/cancel",
    request: { location: "body", schema: cancelRunInputSchema },
    response: codexCancelRunResultSchema
  }),
  approveAction: defineEndpoint({
    method: "POST",
    path: "/api/codex/approvals",
    request: { location: "body", schema: approveActionRequestSchema }
  }),
  sendRepositoryChatMessage: defineEndpoint({
    method: "POST",
    path: "/api/codex/repository-chat",
    request: { location: "body", schema: repositoryChatInputSchema },
    response: repositoryChatResponseSchema
  }),
  readRunEvents: defineEndpoint({
    method: "GET",
    path: "/api/codex/run-events",
    request: { location: "query", schema: projectTicketRunRequestSchema },
    response: arrayOf(rendererRunEventSchema)
  }),
  readLatestRunSummary: defineEndpoint({
    method: "GET",
    path: "/api/codex/run-summary",
    request: { location: "query", schema: projectTicketRequestSchema },
    response: Schema.NullOr(runSummarySchema)
  })
} as const;

import { Schema } from "effect";
import { clarificationQuestionSchema } from "./clarification";
import {
  isoString,
  mutableArray,
  numberSchema,
  passthroughStruct,
  unknownRecordSchema,
  type RelaySchema,
  type RelaySchemaTop,
  type SchemaType
} from "./common";
import { relayActorSchema, relayEventSourceSchema, runStatusSchema } from "./primitives";

export const startRunInputSchema = passthroughStruct({
  projectPath: Schema.String,
  ticketId: Schema.String,
  freshThread: Schema.optional(Schema.Boolean),
  resume: Schema.optional(Schema.Boolean)
});
export type StartRunInput = SchemaType<typeof startRunInputSchema>;

export const codexCancelRunOutcomeSchema = Schema.Literals(["cancelled", "paused", "discarded"]);
export type CodexCancelRunOutcome = SchemaType<typeof codexCancelRunOutcomeSchema>;

export const cancelRunInputSchema = passthroughStruct({
  projectPath: Schema.String,
  ticketId: Schema.String,
  runId: Schema.String,
  revertChanges: Schema.optional(Schema.Boolean)
});
export type CancelRunInput = SchemaType<typeof cancelRunInputSchema>;

export const codexCancelRunResultSchema = passthroughStruct({
  outcome: codexCancelRunOutcomeSchema,
  revertMessage: Schema.NullOr(Schema.String)
});
export type CodexCancelRunResult = SchemaType<typeof codexCancelRunResultSchema>;

export const repositoryChatInputSchema = passthroughStruct({
  projectPath: Schema.String,
  message: Schema.String,
  threadId: Schema.optional(Schema.NullOr(Schema.String))
});
export type RepositoryChatInput = SchemaType<typeof repositoryChatInputSchema>;

export const repositoryChatResponseSchema = Schema.Struct({
  threadId: Schema.String,
  message: Schema.String
});
export type RepositoryChatResponse = SchemaType<typeof repositoryChatResponseSchema>;

export const relayApprovalDecisionSchema = Schema.Literals([
  "accept",
  "acceptForSession",
  "decline",
  "cancel"
]);
export type RelayApprovalDecision = SchemaType<typeof relayApprovalDecisionSchema>;

export const codexStatusSchema = Schema.Struct({
  sdkAvailable: Schema.Boolean,
  cliAvailable: Schema.Boolean,
  cliVersion: Schema.NullOr(Schema.String),
  authenticated: Schema.NullOr(Schema.Boolean),
  message: Schema.String
});
export type CodexStatus = SchemaType<typeof codexStatusSchema>;

export const codexRunStartResultSchema = Schema.Struct({
  state: Schema.Literals(["queued", "started"]),
  runId: Schema.String,
  threadId: Schema.NullOr(Schema.String)
});
export type CodexRunStartResult = SchemaType<typeof codexRunStartResultSchema>;

export const codexRunPreflightResultSchema = Schema.Struct({
  ok: Schema.Boolean,
  errors: mutableArray(Schema.String),
  warnings: mutableArray(Schema.String),
  ticketStatus: Schema.NullOr(Schema.String),
  runStatus: Schema.NullOr(runStatusSchema),
  unansweredClarificationCount: numberSchema,
  canStartFreshThread: Schema.Boolean
});
export type CodexRunPreflightResult = SchemaType<typeof codexRunPreflightResultSchema>;

const relayCodexEventTypeSchema = Schema.Literals([
  "run.started",
  "agent.message.delta",
  "agent.message.completed",
  "command.started",
  "command.output",
  "command.completed",
  "file.change",
  "web.search",
  "todo.updated",
  "mcp.tool_call",
  "approval.requested",
  "approval.resolved",
  "ticket.status_changed",
  "clarification.requested",
  "run.completed",
  "run.failed"
]);

const relayCodexEventMembers = [
  Schema.Struct({ type: Schema.Literal("run.started"), runId: Schema.String, threadId: Schema.String, timestamp: isoString }),
  Schema.Struct({ type: Schema.Literal("agent.message.delta"), text: Schema.String, timestamp: isoString }),
  Schema.Struct({ type: Schema.Literal("agent.message.completed"), text: Schema.String, timestamp: isoString }),
  Schema.Struct({ type: Schema.Literal("command.started"), command: Schema.String, cwd: Schema.optional(Schema.String), timestamp: isoString }),
  Schema.Struct({
    type: Schema.Literal("command.output"),
    stream: Schema.Literals(["stdout", "stderr"]),
    text: Schema.String,
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("command.completed"),
    status: Schema.Literals(["completed", "failed", "declined"]),
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("file.change"),
    path: Schema.String,
    kind: Schema.optional(Schema.String),
    summary: Schema.optional(Schema.String),
    timestamp: isoString
  }),
  Schema.Struct({ type: Schema.Literal("web.search"), query: Schema.String, timestamp: isoString }),
  Schema.Struct({
    type: Schema.Literal("todo.updated"),
    items: mutableArray(Schema.Struct({ text: Schema.String, completed: Schema.Boolean })),
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("mcp.tool_call"),
    server: Schema.String,
    tool: Schema.String,
    status: Schema.Literals(["in_progress", "completed", "failed"]),
    error: Schema.optional(Schema.String),
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("approval.requested"),
    approvalId: Schema.String,
    kind: Schema.Literals(["command", "file-change", "network", "other"]),
    payload: unknownRecordSchema,
    timestamp: isoString
  }),
  Schema.Struct({ type: Schema.Literal("approval.resolved"), approvalId: Schema.String, decision: Schema.String, timestamp: isoString }),
  Schema.Struct({
    type: Schema.Literal("ticket.status_changed"),
    fromStatus: Schema.String,
    toStatus: Schema.String,
    actor: relayActorSchema,
    source: relayEventSourceSchema,
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("clarification.requested"),
    questions: mutableArray(clarificationQuestionSchema),
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("run.completed"),
    finalResponse: Schema.String,
    usage: Schema.optional(Schema.Unknown),
    finalStatus: Schema.optional(runStatusSchema),
    timestamp: isoString
  }),
  Schema.Struct({
    type: Schema.Literal("run.failed"),
    message: Schema.String,
    details: Schema.optional(Schema.Unknown),
    finalStatus: Schema.optional(runStatusSchema),
    timestamp: isoString
  })
] as const;

export const relayCodexEventSchema = Schema.Union(relayCodexEventMembers);
export type RelayCodexEvent = SchemaType<typeof relayCodexEventSchema>;

const rendererRunEventFields = {
  projectPath: Schema.String,
  ticketId: Schema.String,
  runId: Schema.String
} as const;

const rendererRunEventMembers = relayCodexEventMembers.map((member) =>
  member.mapFields((fields) => ({ ...fields, ...rendererRunEventFields }))
) as unknown as readonly RelaySchemaTop[];

export const rendererRunEventSchema = Schema.Union(rendererRunEventMembers) as RelaySchema<RelayCodexEvent & {
  projectPath: string;
  ticketId: string;
  runId: string;
}>;
export type RendererRunEvent = SchemaType<typeof rendererRunEventSchema>;

export const runLogLineSchema = Schema.Struct({
  schemaVersion: numberSchema,
  timestamp: isoString,
  ticketId: Schema.String,
  runId: Schema.String,
  threadId: Schema.String,
  type: relayCodexEventTypeSchema,
  payload: unknownRecordSchema
});
export type RunLogLine = SchemaType<typeof runLogLineSchema>;

export const runUsageSummarySchema = Schema.Struct({
  inputTokens: Schema.NullOr(numberSchema),
  cachedInputTokens: Schema.NullOr(numberSchema),
  outputTokens: Schema.NullOr(numberSchema),
  reasoningOutputTokens: Schema.NullOr(numberSchema),
  totalTokens: Schema.NullOr(numberSchema)
});
export type RunUsageSummary = SchemaType<typeof runUsageSummarySchema>;

export const runSummarySchema = Schema.Struct({
  schemaVersion: numberSchema,
  ticketId: Schema.String,
  runId: Schema.String,
  threadId: Schema.NullOr(Schema.String),
  startedAt: Schema.NullOr(isoString),
  endedAt: Schema.NullOr(isoString),
  durationMs: Schema.NullOr(numberSchema),
  finalStatus: Schema.NullOr(runStatusSchema),
  usage: Schema.NullOr(runUsageSummarySchema),
  eventCount: numberSchema,
  latestEventAt: Schema.NullOr(isoString)
});
export type RunSummary = SchemaType<typeof runSummarySchema>;

import { Schema } from "effect";
import type { RelaySchema } from "../schemas";

export type HttpMethod = "GET" | "POST" | "PUT" | "DELETE";
export type HttpRequestLocation = "query" | "body";

export type HttpRequestRule<Request> = {
  readonly location: HttpRequestLocation;
  readonly schema: RelaySchema<Request>;
};

export type HttpEndpoint<Request, Response> = {
  readonly method: HttpMethod;
  readonly path: `/api/${string}`;
  readonly request?: HttpRequestRule<Request>;
  readonly response?: RelaySchema<Response>;
};

export type AnyHttpEndpoint = HttpEndpoint<unknown, unknown>;
export type HttpEndpointRequest<Endpoint> = Endpoint extends HttpEndpoint<infer Request, unknown> ? Request : never;
export type HttpEndpointResponse<Endpoint> = Endpoint extends HttpEndpoint<unknown, infer Response> ? Response : never;

export const defineEndpoint = <Request, Response>(endpoint: HttpEndpoint<Request, Response>): HttpEndpoint<Request, Response> => endpoint;

export const arrayOf = <A>(schema: RelaySchema<A>): RelaySchema<A[]> =>
  Schema.mutable(Schema.Array(schema)) as RelaySchema<A[]>;

export const apiErrorSchema = Schema.Struct({
  code: Schema.String,
  message: Schema.String
});
export type ApiErrorPayload = typeof apiErrorSchema.Type;

export const apiErrorResponseSchema = Schema.Struct({
  error: apiErrorSchema
});
export type ApiErrorResponse = typeof apiErrorResponseSchema.Type;

import { Context, Effect, Layer } from "effect";
import type { AgentTicketUpdateInput, CreateDraftInput, StartRunInput, TicketRedraftInput } from "@shared/schemas";
import { RegistryStore, RegistryStoreLive } from "../registry";
import type { BackendIoServices, BackendServicesBase } from "../../runtime";
import { runBackendEffect } from "../../runtime";
import { WorkEngine, WorkEngineLive, workStatusFromLegacyStatus, type WorkRecoveryReport } from "./engine";
import { WorkLedger, WorkLedgerLive } from "./ledger";
import { WorkRecovery, WorkRecoveryLive } from "./recovery";
import { WorkRuntime, WorkRuntimeLive } from "./runtime";
import { WorkScheduler, WorkSchedulerLive } from "./scheduler";
import { TicketWorkService, TicketWorkServiceLive } from "./ticket";
import { WorkLeaseMismatchError, type WorkError, type WorkHandle, type WorkRunSnapshot, type WorkStatus } from "./domain";

export * from "./domain";
export * from "./engine";
export * from "./ledger";
export * from "./ports";
export * from "./recovery";
export * from "./runtime";
export * from "./scheduler";
export * from "./ticket";

export type WorkExecutionStatus = WorkStatus;

export const BackendWorkBaseLive = Layer.mergeAll(
  WorkLedgerLive,
  WorkSchedulerLive,
  WorkEngineLive,
  TicketWorkServiceLive,
  WorkRuntimeLive,
  WorkRecoveryLive
);

export type BackendWorkBaseServices =
  | Context.Service.Identifier<typeof WorkLedger>
  | Context.Service.Identifier<typeof WorkScheduler>
  | Context.Service.Identifier<typeof WorkEngine>
  | Context.Service.Identifier<typeof TicketWorkService>
  | Context.Service.Identifier<typeof WorkRuntime>
  | Context.Service.Identifier<typeof WorkRecovery>;

export type BackendWorkServices = BackendWorkBaseServices;
export type BackendWorkRequirements = BackendServicesBase | BackendIoServices;

export const BackendWorkLive: Layer.Layer<BackendWorkServices, never, BackendWorkRequirements> = BackendWorkBaseLive;

type WorkPromiseServices = BackendWorkServices | BackendWorkRequirements | Context.Service.Identifier<typeof RegistryStore>;

const WorkPromiseLive = Layer.mergeAll(BackendWorkLive, RegistryStoreLive);

const runWork = <A>(effect: Effect.Effect<A, WorkError, WorkPromiseServices>): Promise<A> =>
  runBackendEffect(Effect.provide(effect, WorkPromiseLive));

export const submitTicketDraftWork = (
  input: CreateDraftInput,
  options: { readonly runId: string; readonly ticketId: string }
): Promise<WorkHandle> =>
  runWork(TicketWorkService.use((service) => service.submitDraft(input, options)));

export const submitTicketRedraftWork = (
  input: TicketRedraftInput,
  options: { readonly runId: string }
): Promise<WorkHandle> =>
  runWork(TicketWorkService.use((service) => service.submitRedraft(input, options)));

export const submitTicketUpdateWork = (
  input: AgentTicketUpdateInput,
  options: { readonly runId: string }
): Promise<WorkHandle> =>
  runWork(TicketWorkService.use((service) => service.submitUpdate(input, options)));

export const submitTicketImplementationWork = (
  input: StartRunInput,
  options: { readonly runId: string; readonly resume: boolean }
): Promise<WorkHandle> =>
  runWork(TicketWorkService.use((service) => service.submitImplementation(input, options)));

export const claimImplementationWork = async (
  projectPath: string,
  workId?: string | null
): Promise<import("./domain").WorkClaim | null> =>
  runWork(
    WorkEngine.use((engine) =>
      engine.claimNext({
        projectPath,
        workId,
        executor: "agent",
        providerId: "codex"
      })
    )
  );

export const claimWorkRun = (
  projectPath: string,
  runId: string,
  options: {
    readonly executor?: import("./domain").WorkExecutor;
    readonly providerId?: string | null;
    readonly providerSessionRef?: import("./domain").ProviderSessionRef | null;
  } = {}
): Promise<import("./domain").WorkClaim | null> =>
  runWork(
    WorkEngine.use((engine) =>
      engine.claimWork({
        projectPath,
        workId: runId,
        executor: options.executor ?? "agent",
        providerId: options.providerId ?? "codex",
        providerSessionRef: options.providerSessionRef
      })
    )
  );

export const markWorkRunStatus = (
  projectPath: string,
  runId: string,
  status: WorkStatus | "submitted" | "suspended",
  options: {
    readonly result?: unknown;
    readonly error?: unknown;
    readonly message?: string;
    readonly metadata?: Record<string, unknown>;
    readonly attemptId?: string | null;
    readonly leaseToken?: string | null;
  } = {}
): Promise<WorkRunSnapshot | null> =>
  runWork(
    Effect.gen(function*() {
      const workStatus = workStatusFromLegacyStatus(status);
      const providerSessionRef = options.metadata?.providerSessionRef as import("./domain").ProviderSessionRef | undefined;
      const engine = yield* WorkEngine;
      const ledger = yield* WorkLedger;
      const snapshot = yield* engine.findByRunId(projectPath, runId);
      if (!snapshot) return null;
      const attempt = options.attemptId && options.leaseToken
        ? {
          attemptId: options.attemptId,
          leaseToken: options.leaseToken
        }
        : null;

      if (attempt && workStatus === "running") {
        return yield* engine.reportStarted({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          attemptId: attempt.attemptId,
          leaseToken: attempt.leaseToken,
          providerSessionRef: options.metadata?.providerSessionRef as import("./domain").ProviderSessionRef | undefined,
          message: options.message,
          metadata: options.metadata
        });
      }
      if (attempt && workStatus === "blocked") {
        return yield* engine.reportBlocked({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          attemptId: attempt.attemptId,
          leaseToken: attempt.leaseToken,
          reason: options.message ?? "Work blocked.",
          result: options.result,
          metadata: options.metadata
        });
      }
      if (attempt && workStatus === "completed") {
        return yield* engine.reportCompleted({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          attemptId: attempt.attemptId,
          leaseToken: attempt.leaseToken,
          result: options.result,
          message: options.message,
          metadata: options.metadata
        });
      }
      if (attempt && workStatus === "failed") {
        return yield* engine.reportFailed({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          attemptId: attempt.attemptId,
          leaseToken: attempt.leaseToken,
          error: options.error,
          message: options.message ?? "Work failed.",
          metadata: options.metadata
        });
      }
      if (attempt && workStatus === "cancelled") {
        return yield* engine.reportCancelled({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          attemptId: attempt.attemptId,
          leaseToken: attempt.leaseToken,
          message: options.message,
          metadata: options.metadata
        });
      }

      if (!attempt && workStatus === "running") {
        const claim = yield* engine.claimWork({
          projectPath: snapshot.projectPath,
          workId: snapshot.workId,
          executor: "agent",
          providerId: typeof options.metadata?.providerId === "string" ? options.metadata.providerId : "codex",
          providerSessionRef
        });
        if (!claim) return snapshot;
        return yield* engine.reportStarted({
          projectPath: claim.projectPath,
          workId: claim.workId,
          attemptId: claim.attemptId,
          leaseToken: claim.leaseToken,
          providerSessionRef,
          message: options.message,
          metadata: options.metadata
        });
      }

      if (!attempt && snapshot.currentAttempt) {
        return yield* Effect.fail(
          new WorkLeaseMismatchError({
            workId: snapshot.workId,
            attemptId: snapshot.currentAttempt.attemptId,
            message: `Work ${snapshot.workId} has an active attempt and requires attempt credentials.`
          })
        );
      }

      let transitionBase = snapshot;
      if (
        (transitionBase.status === "created" && workStatus !== "created") ||
        (transitionBase.status === "queued" && (workStatus === "blocked" || workStatus === "completed" || workStatus === "failed"))
      ) {
        transitionBase = yield* ledger.transition({
          projectPath: transitionBase.projectPath,
          workId: transitionBase.workId,
          status: transitionBase.status === "created" ? "queued" : "running",
          providerSessionRef,
          message: "Work advanced for terminal report compatibility."
        });
      }

      return yield* ledger.transition({
        projectPath: transitionBase.projectPath,
        workId: transitionBase.workId,
        status: workStatus,
        result: options.result,
        error: options.error,
        providerSessionRef,
        message: options.message,
        metadata: options.metadata
      });
    })
  );

export const recoverWorkFromRegistry = (): Promise<WorkRecoveryReport[]> =>
  runWork(WorkEngine.use((engine) => engine.recoverAll()));

import { Context, Effect, FileSystem, Layer, Path } from "effect";
import { ulid } from "ulid";
import { BackendClock } from "../../../platform";
import { isFileNotFoundError } from "../../../platform/PlatformError";
import type { BackendIoServices, BackendServicesBase } from "../../../runtime";
import { workRunEventsPath, workRunsPath, workRunSnapshotPath } from "../../../storage/paths";
import {
  applyWorkTransition,
  isTerminalWorkStatus,
  RELAY_WORK_SCHEMA_VERSION,
  snapshotToWorkHandle,
  validateWorkTransition,
  workEventTypeForStatus,
  type WorkEvent,
  type WorkEventType,
  type WorkHandle,
  type WorkRunSnapshot,
  type WorkSubmitInput,
  type WorkTransitionInput
} from "../domain";
import {
  WorkJsonParseError,
  WorkNotFoundError,
  WorkPersistenceError,
  type WorkError,
  workPersistenceError
} from "../domain";

type WorkBaseServices = BackendServicesBase | BackendIoServices;
type WorkEffect<A> = Effect.Effect<A, WorkError, WorkBaseServices>;

const processLocks = new Map<string, Promise<void>>();

const acquireProcessLock = (key: string): Effect.Effect<() => void> =>
  Effect.promise(async () => {
    const previous = processLocks.get(key) ?? Promise.resolve();
    let release!: () => void;
    const lock = new Promise<void>((resolve) => {
      release = resolve;
    });
    const current = previous.catch(() => undefined).then(() => lock);
    processLocks.set(key, current);
    await previous.catch(() => undefined);
    let released = false;
    return () => {
      if (released) return;
      released = true;
      release();
      if (processLocks.get(key) === current) processLocks.delete(key);
    };
  });

const withProcessLock = <A, E, R>(key: string, effect: Effect.Effect<A, E, R>): Effect.Effect<A, E, R> =>
  Effect.uninterruptibleMask((restore) =>
    Effect.flatMap(acquireProcessLock(key), (release) =>
      Effect.ensuring(restore(effect), Effect.sync(release))
    )
  );

export type WorkLedgerService = {
  readonly submit: (input: WorkSubmitInput) => WorkEffect<WorkRunSnapshot>;
  readonly transition: (input: WorkTransitionInput) => WorkEffect<WorkRunSnapshot>;
  readonly readSnapshot: (projectPath: string, workId: string) => WorkEffect<WorkRunSnapshot | null>;
  readonly readEvents: (projectPath: string, workId: string) => WorkEffect<WorkEvent[]>;
  readonly listProjectWork: (projectPath: string) => WorkEffect<WorkRunSnapshot[]>;
  readonly listIncomplete: (projectPath: string) => WorkEffect<WorkRunSnapshot[]>;
  readonly findByRunId: (projectPath: string, runId: string) => WorkEffect<WorkRunSnapshot | null>;
  readonly findByIdempotencyKey: (
    projectPath: string,
    kind: string,
    idempotencyKey: string
  ) => WorkEffect<WorkRunSnapshot | null>;
};

export const WorkLedger = Context.Service<WorkLedgerService>("relay/WorkLedger");

const safeWorkId = (workId: string): string => workId.replace(/[^a-zA-Z0-9._-]/g, "_");

const newWorkEventId = (): string => `wevt_${ulid().toLowerCase()}`;
const newWorkId = (): string => `work_${ulid().toLowerCase()}`;

const parseJson = <A>(raw: string, target: string): Effect.Effect<A, WorkJsonParseError> =>
  Effect.try({
    try: () => JSON.parse(raw) as A,
    catch: (cause) =>
      new WorkJsonParseError({
        target,
        message: `Could not parse work JSON at ${target}: ${cause instanceof Error ? cause.message : String(cause)}`,
        cause
      })
  });

const readJsonOrNull = <A>(target: string): Effect.Effect<A | null, WorkJsonParseError | WorkPersistenceError, BackendIoServices> =>
  FileSystem.FileSystem.use((fs) => fs.readFileString(target, "utf8")).pipe(
    Effect.catchIf(isFileNotFoundError, () => Effect.succeed(null as string | null)),
    Effect.mapError((cause) => workPersistenceError(target, "read work JSON", cause)),
    Effect.flatMap((raw) => raw === null ? Effect.succeed(null) : parseJson<A>(raw, target))
  );

const atomicWriteTextEffect = (target: string, value: string): Effect.Effect<void, WorkPersistenceError, BackendIoServices> =>
  Effect.gen(function*() {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    yield* fs.makeDirectory(path.dirname(target), { recursive: true });
    const tmp = `${target}.${ulid().toLowerCase()}.tmp`;
    yield* fs.writeFileString(tmp, value);
    yield* fs.rename(tmp, target);
  }).pipe(Effect.mapError((cause) => workPersistenceError(target, "write work JSON", cause)));

const appendEvent = (event: WorkEvent): WorkEffect<void> =>
  Effect.gen(function*() {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const target = workRunEventsPath(path, event.projectPath, safeWorkId(event.workId));
    yield* fs.makeDirectory(path.dirname(target), { recursive: true });
    yield* fs.writeFileString(target, `${JSON.stringify(event)}\n`, { flag: "a" });
  }).pipe(
    Effect.mapError((cause) =>
      cause instanceof WorkPersistenceError
        ? cause
        : workPersistenceError(`${event.projectPath}:${event.workId}`, "append work event", cause)
    )
  );

const writeSnapshot = (snapshot: WorkRunSnapshot): WorkEffect<void> =>
  Effect.gen(function*() {
    const path = yield* Path.Path;
    yield* atomicWriteTextEffect(
      workRunSnapshotPath(path, snapshot.projectPath, safeWorkId(snapshot.workId)),
      `${JSON.stringify(snapshot, null, 2)}\n`
    );
  });

const makeEvent = (
  snapshot: WorkRunSnapshot,
  type: WorkEventType,
  timestamp: string,
  options: Pick<WorkEvent, "attemptId" | "payload" | "message" | "metadata"> = {}
): WorkEvent => ({
  schemaVersion: RELAY_WORK_SCHEMA_VERSION,
  eventId: newWorkEventId(),
  workId: snapshot.workId,
  attemptId: options.attemptId ?? snapshot.currentAttempt?.attemptId ?? null,
  sequence: snapshot.lastAppliedEventSequence + 1,
  timestamp,
  type,
  projectPath: snapshot.projectPath,
  ticketId: snapshot.ticketId,
  runId: snapshot.runId,
  payload: options.payload,
  message: options.message,
  metadata: options.metadata
});

const readSnapshot = (projectPath: string, workId: string): WorkEffect<WorkRunSnapshot | null> =>
  Effect.gen(function*() {
    const path = yield* Path.Path;
    return yield* readJsonOrNull<WorkRunSnapshot>(workRunSnapshotPath(path, projectPath, safeWorkId(workId)));
  });

const submit = (input: WorkSubmitInput): WorkEffect<WorkRunSnapshot> =>
  withProcessLock(`work-submit:${input.projectPath}`, Effect.gen(function*() {
    const existingById = input.workId ? yield* readSnapshot(input.projectPath, input.workId) : null;
    if (existingById) return existingById;
    const existingByKey = yield* findByIdempotencyKey(input.projectPath, input.kind, input.idempotencyKey);
    if (existingByKey) return existingByKey;

    const clock = yield* BackendClock;
    const now = clock.nowIso();
    const workId = input.workId ?? input.runId ?? newWorkId();
    const snapshot: WorkRunSnapshot = {
      schemaVersion: RELAY_WORK_SCHEMA_VERSION,
      workId,
      projectPath: input.projectPath,
      ticketId: input.ticketId ?? null,
      runId: input.runId ?? workId,
      subject: input.subject,
      action: input.action,
      kind: input.kind,
      idempotencyKey: input.idempotencyKey,
      status: "created",
      attempts: 0,
      createdAt: now,
      updatedAt: now,
      lastAppliedEventSequence: 0,
      executor: input.executor,
      providerId: input.providerId ?? null,
      requiredCapabilities: input.requiredCapabilities,
      providerCapabilities: input.providerCapabilities,
      providerSessionRef: input.providerSessionRef ?? null,
      currentAttempt: null,
      payload: input.payload,
      metadata: input.metadata
    };
    const event = makeEvent(snapshot, "work.submitted", now, {
      payload: input.payload,
      metadata: input.metadata
    });
    const submitted = { ...snapshot, lastAppliedEventSequence: event.sequence };
    yield* appendEvent(event);
    yield* writeSnapshot(submitted);
    return submitted;
  }));

const transition = (input: WorkTransitionInput): WorkEffect<WorkRunSnapshot> =>
  withProcessLock(`work:${input.projectPath}:${input.workId}`, Effect.gen(function*() {
    const current = yield* readSnapshot(input.projectPath, input.workId);
    if (!current) {
      return yield* Effect.fail(
        new WorkNotFoundError({
          projectPath: input.projectPath,
          workId: input.workId,
          message: `Work does not exist: ${input.workId}`
        })
      );
    }

    if (current.status === input.status && isTerminalWorkStatus(current.status)) return current;
    const invalid = validateWorkTransition(current, input);
    if (invalid) return yield* Effect.fail(invalid);

    const clock = yield* BackendClock;
    const now = clock.nowIso();
    const event = makeEvent(current, input.eventType ?? workEventTypeForStatus(input.status), now, {
      attemptId: input.attemptId ?? input.attempt?.attemptId ?? current.currentAttempt?.attemptId ?? null,
      payload: input.payload ?? input.result ?? input.error,
      message: input.message,
      metadata: input.metadata
    });
    const next = applyWorkTransition(current, input, now, event.sequence);
    yield* appendEvent(event);
    yield* writeSnapshot(next);
    return next;
  }));

const readEvents = (projectPath: string, workId: string): WorkEffect<WorkEvent[]> =>
  Effect.gen(function*() {
    const path = yield* Path.Path;
    const target = workRunEventsPath(path, projectPath, safeWorkId(workId));
    const raw = yield* FileSystem.FileSystem.use((fs) => fs.readFileString(target, "utf8")).pipe(
      Effect.catchIf(isFileNotFoundError, () => Effect.succeed("")),
      Effect.mapError((cause) => workPersistenceError(target, "read work events", cause))
    );
    const clock = yield* BackendClock;
    const lines = raw.split("\n");
    const events: WorkEvent[] = [];
    for (const [index, line] of lines.entries()) {
      if (!line.trim()) continue;
      try {
        events.push(JSON.parse(line) as WorkEvent);
      } catch (cause) {
        const hasLaterNonEmptyLine = lines.slice(index + 1).some((later) => later.trim());
        if (hasLaterNonEmptyLine) {
          return yield* Effect.fail(
            new WorkJsonParseError({
              target,
              message: `Could not parse work event at ${target}:${index + 1}.`,
              cause
            })
          );

          );
        }
        events.push({
          schemaVersion: RELAY_WORK_SCHEMA_VERSION,
          eventId: newWorkEventId(),
          workId,
          attemptId: null,
          sequence: events.length + 1,
          timestamp: clock.nowIso(),
          type: "work.corrupt_event_ignored",
          projectPath,
          payload: { line: index + 1 },
          message: `Ignored corrupt trailing work event at line ${index + 1}.`,
          metadata: { line: index + 1 }
        });
      }
    }
    return events;
  });

const listProjectWork = (projectPath: string): WorkEffect<WorkRunSnapshot[]> =>
  Effect.gen(function*() {
    const path = yield* Path.Path;
    const target = workRunsPath(path, projectPath);
    const names = yield* FileSystem.FileSystem.use((fs) => fs.readDirectory(target)).pipe(
      Effect.catchIf(isFileNotFoundError, () => Effect.succeed<string[]>([])),
      Effect.mapError((cause) => workPersistenceError(target, "list work runs", cause))
    );
    const snapshots: WorkRunSnapshot[] = [];
    for (const name of names) {
      const snapshot = yield* Effect.catch(readSnapshot(projectPath, name), () => Effect.succeed(null));
      if (snapshot) snapshots.push(snapshot);
    }
    return snapshots.sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  });

const listIncomplete = (projectPath: string): WorkEffect<WorkRunSnapshot[]> =>
  Effect.map(listProjectWork(projectPath), (snapshots) => snapshots.filter((snapshot) => !isTerminalWorkStatus(snapshot.status)));

const findByRunId = (projectPath: string, runId: string): WorkEffect<WorkRunSnapshot | null> =>
  Effect.map(
    listProjectWork(projectPath),
    (snapshots) => snapshots.find((snapshot) => snapshot.runId === runId || snapshot.workId === runId || snapshot.payload.runId === runId) ?? null
  );

const findByIdempotencyKey = (projectPath: string, kind: string, idempotencyKey: string): WorkEffect<WorkRunSnapshot | null> =>
  Effect.map(
    listProjectWork(projectPath),
    (snapshots) =>
      snapshots.find((snapshot) => snapshot.kind === kind && snapshot.idempotencyKey === idempotencyKey) ?? null
  );

export const WorkLedgerLive = Layer.succeed(WorkLedger)({
  submit,
  transition,
  readSnapshot,
  readEvents,
  listProjectWork,
  listIncomplete,
  findByRunId,
  findByIdempotencyKey
});

