import { Effect } from "effect";
import { ticketEndpoints } from "@shared/http";
import type { TicketDraftStartResult } from "@shared/schemas";
import { fromPromise } from "../../runtime";
import { BoardWorkflows, TicketWorkflows } from "../../workflows";
import {
  approveScopeClarificationRedraft,
  cancelTicketUpdateRun,
  createDraftIntake,
  maybeFinalizeImplementationScopeAfterClarification,
  maybeResumeTicketDraftAfterClarification,
  startTicketDraftRun,
  startTicketRedraftRun,
  startTicketUpdateRun,
  ticketDraftErrorToPayload
} from "../../services/codex";
import { notifyTicketReadyForScheduling } from "../../services/codex/readyTicketScheduler";
import { logError } from "../../runtime/Logging";
import { httpRunEventSink } from "./runEventSink";
import { route, type HttpResourceRoute } from "./types";

export const ticketRoutes = [
  route(ticketEndpoints.intakeDraft, (input) => fromPromise(() => createDraftIntake(input))),
  route(ticketEndpoints.createDraft, (input) =>
    fromPromise(async (): Promise<TicketDraftStartResult> => {
      try {
        return { ok: true, ...(await startTicketDraftRun(input, { runEventSink: httpRunEventSink() })) };
      } catch (error) {
        return { ok: false, error: ticketDraftErrorToPayload(error) };
      }
    })
  ),
  route(ticketEndpoints.redraft, (input) =>
    fromPromise(async (): Promise<TicketDraftStartResult> => {
      try {
        return { ok: true, ...(await startTicketRedraftRun(input, { runEventSink: httpRunEventSink() })) };
      } catch (error) {
        return { ok: false, error: ticketDraftErrorToPayload(error) };
      }
    })
  ),
  route(ticketEndpoints.createManual, ({ projectPath, input }) => TicketWorkflows.createManualTicket(projectPath, input)),
  route(ticketEndpoints.createSubticket, (input) => TicketWorkflows.createSubticket(input)),
  route(ticketEndpoints.linkSubticket, (input) => TicketWorkflows.linkSubticket(input)),
  route(ticketEndpoints.unlinkSubticket, (input) => TicketWorkflows.unlinkSubticket(input)),
  route(ticketEndpoints.createTaskUnderFeature, (input) => TicketWorkflows.createTaskUnderFeature(input)),
  route(ticketEndpoints.createFeatureSubticket, (input) => TicketWorkflows.createFeatureSubticket(input)),
  route(ticketEndpoints.linkFeatureSubticket, (input) => TicketWorkflows.linkFeatureSubticket(input)),
  route(ticketEndpoints.unlinkFeatureSubticket, (input) => TicketWorkflows.unlinkFeatureSubticket(input)),
  route(ticketEndpoints.startAgentUpdate, (input) =>
    fromPromise(() => startTicketUpdateRun(input, { runEventSink: httpRunEventSink() }))
  ),
  route(ticketEndpoints.cancelAgentUpdate, ({ runId }) => fromPromise(() => cancelTicketUpdateRun(runId))),
  route(ticketEndpoints.references, ({ projectPath }) => TicketWorkflows.listTicketReferences(projectPath)),
  route(ticketEndpoints.read, ({ projectPath, ticketId }) => TicketWorkflows.readTicket(projectPath, ticketId)),
  route(ticketEndpoints.save, (input) =>
    Effect.gen(function*() {
      const saved = yield* TicketWorkflows.saveTicket(input);
      yield* fromPromise(() => notifyTicketReadyForScheduling(input.projectPath, saved.frontMatter.id));
      return saved;
    })
  ),
  route(ticketEndpoints.saveAttachment, (input) => TicketWorkflows.saveTicketAttachment(input)),
  route(ticketEndpoints.move, (input) =>
    Effect.gen(function*() {
      yield* TicketWorkflows.moveTicket(input);
      yield* fromPromise(() => notifyTicketReadyForScheduling(input.projectPath, input.ticketId));
      return yield* BoardWorkflows.readBoard(input.projectPath);
    })
  ),
  route(ticketEndpoints.clarifications, ({ projectPath, ticketId }) =>
    TicketWorkflows.listClarifications(projectPath, ticketId)
  ),
  route(ticketEndpoints.answerClarification, (input) =>
    Effect.gen(function*() {
      const answer = yield* TicketWorkflows.answerClarification(input);
      void maybeFinalizeImplementationScopeAfterClarification(input.projectPath, input.ticketId)
        .then((ticket) => {
          if (ticket?.frontMatter.status === "ready") {
            return notifyTicketReadyForScheduling(input.projectPath, input.ticketId);
          }
        })
        .catch((error) =>
          logError("codex:run", "finalize implementation scope after clarification failed", error, {
            projectPath: input.projectPath,
            ticketId: input.ticketId,
            questionId: input.questionId
          })
        );
      void maybeResumeTicketDraftAfterClarification(input.projectPath, input.ticketId, {
        runEventSink: httpRunEventSink()
      }).catch((error) =>
        logError("codex:draft", "auto-resume after clarification failed", error, {
          projectPath: input.projectPath,
          ticketId: input.ticketId,
          questionId: input.questionId
        })
      );
      return answer;
    })
  ),
  route(ticketEndpoints.approveScopeClarification, (input) =>
    fromPromise(() => approveScopeClarificationRedraft(input, { runEventSink: httpRunEventSink() }))
  ),
  route(ticketEndpoints.delete, ({ projectPath, ticketId }) => TicketWorkflows.deleteTicket(projectPath, ticketId)),
  route(ticketEndpoints.duplicate, ({ projectPath, ticketId }) => TicketWorkflows.duplicateTicket(projectPath, ticketId)),
  route(ticketEndpoints.revealFile, ({ projectPath, ticketId }) => TicketWorkflows.revealTicketFile(projectPath, ticketId))
] satisfies ReadonlyArray<HttpResourceRoute>;

import { randomBytes } from "node:crypto";
import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { Effect } from "effect";
import {
  decodeHttpPayload,
  isHttpPayloadSchemaError,
  type ApiErrorResponse
} from "@shared/http";
import { errorMessage } from "../domain/errors";
import { logInfo } from "../runtime/Logging";
import { addRelayHttpRunEventClient } from "./RelayHttpEvents";
import {
  corsHeadersForOrigin,
  defaultHttpMiddlewares,
  runRequestMiddlewares,
  runResponseMiddlewares,
  type HttpMiddleware,
  type HttpRequestContext,
  type HttpResponseDraft
} from "./middleware";
import { httpResourceRoutes, type HttpResourceRoute } from "./resources";

export type HttpRestApiOptions = {
  readonly host?: string;
  readonly port?: number;
  readonly token?: string;
  readonly routes?: ReadonlyArray<HttpResourceRoute>;
  readonly middlewares?: ReadonlyArray<HttpMiddleware>;
  readonly runEffect: <A, E, R>(effect: Effect.Effect<A, E, R>) => Promise<A>;
};

export type HttpRestApiHandle = {
  readonly baseUrl: string;
  readonly token: string;
  readonly server: Server;
  readonly close: () => Promise<void>;
};

type ApiFailure = {
  readonly status: number;
  readonly code: string;
  readonly message: string;
};

const defaultPort = (): number => {
  const configured = Number.parseInt(process.env.RELAY_API_PORT ?? "", 10);
  if (Number.isInteger(configured) && configured > 0) return configured;
  return process.env.ELECTRON_RENDERER_URL ? 17654 : 0;
};

const defaultToken = (port: number): string => process.env.RELAY_API_TOKEN ?? (port === 17654 ? "relay-dev" : randomBytes(24).toString("base64url"));

const serverAddress = (server: Server, host: string): string => {
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Relay HTTP API did not report a listening address.");
  return `http://${host}:${address.port}`;
};

const jsonResponse = (status: number, body: unknown): HttpResponseDraft => ({
  status,
  body: JSON.stringify(body)
});

const noContentResponse = (): HttpResponseDraft => ({ status: 204 });

const apiErrorResponse = (failure: ApiFailure): HttpResponseDraft =>
  jsonResponse(failure.status, {
    error: {
      code: failure.code,
      message: failure.message
    }
  } satisfies ApiErrorResponse);

const writeResponse = (response: ServerResponse, draft: HttpResponseDraft): void => {
  response.writeHead(draft.status, draft.headers ?? {});
  response.end(draft.body);
};

const writeMiddlewareResponse = async (
  response: ServerResponse,
  middlewares: ReadonlyArray<HttpMiddleware>,
  context: HttpRequestContext,
  draft: HttpResponseDraft
): Promise<void> => {
  writeResponse(response, await Effect.runPromise(runResponseMiddlewares(middlewares, context, draft)));
};

const failureFromError = (error: unknown): ApiFailure => {
  if (isHttpPayloadSchemaError(error)) {
    return { status: 400, code: "api_validation_error", message: errorMessage(error) };
  }
  if (error instanceof SyntaxError) {
    return { status: 400, code: "api_validation_error", message: "Relay API request body must be valid JSON." };
  }
  return { status: 500, code: "api_error", message: errorMessage(error) };
};

const readJsonBody = async (request: IncomingMessage): Promise<unknown> => {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  const body = Buffer.concat(chunks).toString("utf8").trim();
  if (!body) return undefined;
  return JSON.parse(body);
};

const queryObject = (url: URL): Record<string, string> => {
  const query: Record<string, string> = {};
  for (const [key, value] of url.searchParams) {
    if (key !== "token") query[key] = value;
  }
  return query;
};

const routeFor = (
  routes: ReadonlyArray<HttpResourceRoute>,
  method: string | undefined,
  pathname: string
): HttpResourceRoute | undefined =>
  routes.find((route) => route.endpoint.method === method && route.endpoint.path === pathname);

const decodeRouteRequest = async (route: HttpResourceRoute, request: IncomingMessage, url: URL): Promise<unknown> => {
  const rule = route.endpoint.request;
  if (!rule) return undefined;
  const payload = rule.location === "query" ? queryObject(url) : await readJsonBody(request);
  return decodeHttpPayload(rule.schema, payload);
};

const handleRoute = async (
  route: HttpResourceRoute,
  request: IncomingMessage,
  url: URL,
  runEffect: HttpRestApiOptions["runEffect"]
): Promise<HttpResponseDraft> => {
  const input = await decodeRouteRequest(route, request, url);
  const result = await runEffect(route.handle(input as never));
  if (!route.endpoint.response) return noContentResponse();
  return jsonResponse(200, decodeHttpPayload(route.endpoint.response, result));
};

export const startHttpRestApi = async ({
  host = "127.0.0.1",
  port = defaultPort(),
  token = defaultToken(port),
  routes = httpResourceRoutes,
  middlewares = defaultHttpMiddlewares(),
  runEffect
}: HttpRestApiOptions): Promise<HttpRestApiHandle> => {
  const server = createServer(async (request, response) => {
    const url = new URL(request.url ?? "/", `http://${request.headers.host ?? host}`);
    const context: HttpRequestContext = {
      request,
      url,
      expectedToken: token,
      corsHeaders: corsHeadersForOrigin(request.headers.origin)
    };

    const requestMiddlewareResult = await Effect.runPromise(runRequestMiddlewares(middlewares, context));
    if (requestMiddlewareResult._tag === "respond") {
      await writeMiddlewareResponse(
        response,
        middlewares,
        requestMiddlewareResult.context ?? context,
        requestMiddlewareResult.response
      );
      return;
    }

    const activeContext = requestMiddlewareResult.context;
    if (activeContext.request.method === "GET" && activeContext.url.pathname === "/api/events") {
      const cleanup = addRelayHttpRunEventClient(response, activeContext.corsHeaders);
      request.on("close", cleanup);
      return;
    }

    const route = routeFor(routes, activeContext.request.method, activeContext.url.pathname);
    if (!route) {
      await writeMiddlewareResponse(
        response,
        middlewares,
        activeContext,
        apiErrorResponse({
          status: 404,
          code: "not_found",
          message: "Relay API route was not found."
        })
      );
      return;
    }

    try {
      await writeMiddlewareResponse(
        response,
        middlewares,
        activeContext,
        await handleRoute(route, request, activeContext.url, runEffect)
      );
    } catch (error) {
      await writeMiddlewareResponse(response, middlewares, activeContext, apiErrorResponse(failureFromError(error)));
    }
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, () => {
      server.off("error", reject);
      resolve();
    });
  });

  const baseUrl = serverAddress(server, host);
  await logInfo("http", "Relay REST API listening", {
    baseUrl,
    token
  });

  return {
    baseUrl,
    token,

